    const project = await this.pick(projects, (p) => p.name, "project", opts.project, byNameOrId);
    const detail = await this.api.get(`/projects/${project.id}`);
    const service = await this.pick(detail.services, (s) => `${s.name} (${s.type})`, "service", opts.service, byNameOrId);
    const env = await this.pick(detail.environments, (e) => e.name, "environment", opts.environment ?? (detail.environments.length > 1 ? "production" : void 0), byNameOrId);
    writeLink(process.cwd(), { projectId: project.id, serviceId: service.id, environmentId: env.id });
