var isEntry = import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("skyhost.js") || process.argv[1]?.endsWith("skyhost");
if (isEntry) {
  main(process.argv.slice(2)).catch((e) => {
    if (e instanceof CliError) {
      if (e.message) console.error(c.red(`Error: ${e.message}`));
      process.exit(e.exitCode);
    }
    if (e.code?.startsWith("ERR_PARSE_ARGS")) {
      console.error(c.red(e.message));
      process.exit(2);
    }
    console.error(e);
    process.exit(1);
  });
}
export {
  main
};
